// Run: node --test web/test/
// Uses the same fixture as the Rust tests (tests/fixtures/snapshot.json,
// generated by `export::tests::golden_snapshot_is_current`).
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { test } from 'node:test';
import {
  analyze, bestExitPath, inNetwork, networkOf, loadSnapshot, locate, ownerRouter, parseIPv6, reachableFrom, singlePointsOfFailure,
} from '../engine.js';
import { detectLang, messages, missingKeys } from '../i18n.js';

const raw = JSON.parse(readFileSync(new URL('../../tests/fixtures/snapshot.json', import.meta.url)));
const topo = loadSnapshot(raw);

test('locates a member address by longest prefix', () => {
  const { prefix, owners } = locate(topo, '10.107.5.130');
  assert.equal(prefix, '10.107.5.128/26');
  assert.equal(owners[0].router, '10.107.5.1');
  assert.equal(locate(topo, '192.168.1.1').owners.length, 0);
});

test('prefers the E1 exit, same path as the Rust engine', () => {
  const p = bestExitPath(topo, '10.107.5.1');
  assert.deepEqual(p.hops.map((h) => h.router), ['10.107.5.1', '10.107.2.1', '10.107.1.1']);
  assert.equal(p.exit.e1, true);
  assert.equal(p.cost, 20);
});

test('single points of failure match Rust', () => {
  const p = bestExitPath(topo, '10.107.5.1');
  const { links, nodes } = singlePointsOfFailure(topo, p);
  assert.deepEqual(links, [['10.107.5.1', '10.107.2.1']]);
  assert.deepEqual(nodes, ['10.107.2.1']);
});

test('isolated router: cut off', () => {
  assert.equal(reachableFrom(topo, '10.107.1.1').has('10.107.9.1'), false);
  const a = analyze(topo, '10.107.9.20');
  assert.equal(a.findings[0].key, 'cutOff');
  assert.equal(a.findings[0].sev, 'critical');
});

test('unrouted address reports the previous owner', () => {
  const a = analyze(topo, '10.107.77.5');
  assert.equal(a.findings[0].key, 'notRouted');
  assert.equal(a.findings[0].params.previous[0].router, '10.107.77.1');
  assert.equal(a.findings[0].params.previous[0].present, false);
});

test('externals locate, aggregates do not', () => {
  assert.equal(locate(topo, '10.200.1.1').owners.length, 0);
  assert.equal(ownerRouter(topo, '10.250.1.9').router, '10.107.2.1');
});

test('an interface address maps to its own router', () => {
  assert.equal(ownerRouter(topo, '10.107.0.2').router, '10.107.2.1');
});

test('healthy member: path, no critical findings', () => {
  const a = analyze(topo, '10.107.5.130');
  assert.equal(a.router, '10.107.5.1');
  assert.equal(a.hops.length, 3);
  assert.ok(a.findings.every((f) => f.sev !== 'critical'));
});

test('parallel links between two routers are a backup', () => {
  const t = loadSnapshot({
    version: 1,
    root: '10.0.0.1',
    routers: {
      '10.0.0.1': { links: [['10.0.0.2', 10, '10.9.0.0/30'], ['10.0.0.2', 10, '10.9.1.0/30']] },
      '10.0.0.2': { links: [['10.0.0.1', 10, '10.9.0.0/30'], ['10.0.0.1', 10, '10.9.1.0/30']] },
    },
    prefixes: [],
    exits: [{ router: '10.0.0.1', target: '10.0.0.1', e1: false, metric: 1 }],
  });
  const p = bestExitPath(t, '10.0.0.2');
  assert.deepEqual(singlePointsOfFailure(t, p).links, []);
});

test('rejects malformed or hostile snapshots', () => {
  assert.throws(() => loadSnapshot({ version: 2, routers: {} }));
  assert.throws(() => loadSnapshot({ version: 1, routers: { '<img src=x>': { links: [] } } }));
  assert.throws(() => loadSnapshot({ version: 1, routers: { '10.0.0.1': { links: [['javascript:1', 1, null]] } } }));
  // Bad prefixes and exits are dropped, not trusted.
  const t = loadSnapshot({ version: 1, routers: {}, prefixes: [['nonsense', '10.0.0.1', 's']], exits: [{ router: 'x', target: 'y' }] });
  assert.equal(t.prefixes.length, 0);
  assert.equal(t.exits.length, 0);
});

test('links to unknown routers and negative costs are rejected or dropped', () => {
  const t = loadSnapshot({ version: 1, routers: { '10.0.0.1': { links: [['10.9.9.9', 10, null]] } }, prefixes: [], exits: [] });
  assert.equal(t.routers.get('10.0.0.1').links.length, 0);
  assert.doesNotThrow(() => analyze(t, '10.0.0.1'));
  assert.throws(() => loadSnapshot({ version: 1, routers: { '10.0.0.1': { links: [['10.0.0.2', -5, null]] }, '10.0.0.2': { links: [] } } }));
});

test('shared interface address: first router wins (as in Rust)', () => {
  const t = loadSnapshot({ version: 1, routers: {
    '10.0.0.1': { links: [], ifaces: ['10.5.5.5'] },
    '10.0.0.2': { links: [], ifaces: ['10.5.5.5'] },
  } });
  assert.equal(t.ifaceOwner.get('10.5.5.5'), '10.0.0.1');
});

test('language detection: Czech default, English when preferred', () => {
  assert.equal(detectLang(['en-US', 'cs']), 'en');
  assert.equal(detectLang(['cs-CZ', 'en']), 'cs');
  assert.equal(detectLang(['sk']), 'cs');
  assert.equal(detectLang(['de-DE', 'en-GB']), 'en');
  assert.equal(detectLang(['de-DE']), 'cs');
  assert.equal(detectLang([]), 'cs');
});

test('both languages define the same messages', () => {
  assert.deepEqual(missingKeys(), []);
});

test('every finding renders in both languages', () => {
  const findings = ['10.107.9.20', '10.107.77.5', '10.107.5.130'].flatMap((ip) => analyze(topo, ip).findings);
  findings.push(
    { key: 'noLsa', params: { router: '10.0.0.1', name: null } },
    { key: 'noExit', params: { router: '10.0.0.1', name: 'AP', count: 3 } },
    { key: 'hopDead', params: { router: '10.0.0.1', name: null } },
    { key: 'hopDegraded', params: { router: '10.0.0.1', name: null, healthText: 'slow' } },
    { key: 'singleExit', params: { reachable: 1, total: 2 } },
  );
  for (const lang of ['cs', 'en']) {
    const T = messages(lang);
    for (const f of findings) {
      const p = { ...f.params };
      if (p.previous) p.previous = p.previous.map((x) => ({ ...x, agoText: 'x' }));
      const [title, lines] = T.f[f.key](p);
      assert.ok(title.length > 0 && Array.isArray(lines), `${lang} ${f.key}`);
      assert.ok(!/undefined|\[object/.test(title + lines.join(' ')), `${lang} ${f.key}: ${title} ${lines}`);
    }
  }
});

test('Czech plurals', () => {
  const T = messages('cs');
  assert.equal(T.ago(86400), 'před 24 h'); // under 48 h shown in hours
  assert.equal(T.ago(86400 * 3), 'před 3 dny');
  assert.equal(T.ago(86400 * 9), 'před 9 dny');
  assert.match(T.f.cutOff({ router: 'r', name: null, advertised: 1, age: 5 })[1][0], /1 spoj,/);
  assert.match(T.f.cutOff({ router: 'r', name: null, advertised: 3, age: 5 })[1][0], /3 spoje,/);
  assert.match(T.f.cutOff({ router: 'r', name: null, advertised: 7, age: 5 })[1][0], /7 spojů,/);
});

// ---------- assistant guide ----------
import { KB, search } from '../kb.js';
import { buildPrompt } from '../assistant.js';

test('guide has the same articles in both languages', () => {
  assert.deepEqual(KB.cs.map((a) => a.id), KB.en.map((a) => a.id));
  for (const lang of ['cs', 'en']) for (const a of KB[lang]) {
    assert.ok(a.title && a.keywords && a.body.length > 0, `${lang} ${a.id}`);
    assert.ok(!/HKFree|HKfree/.test(a.title + a.body.join(' ')), `${lang} ${a.id}: write hkfree.org`);
  }
});

test('guide search finds the right article (Czech with and without diacritics, English)', () => {
  const top = (lang, q) => (search(lang, q)[0] || {}).id;
  assert.equal(top('cs', 'Jak správně restartovat router a anténu?'), 'restart');
  assert.equal(top('cs', 'jak restartovat router'), 'restart');
  assert.equal(top('cs', 'Proč je internet pomalý?'), 'slow');
  assert.equal(top('cs', 'Vyměnil jsem router a nejde to'), 'newrouter');
  assert.equal(top('cs', 'nenačítají se stránky, DNS'), 'dns');
  assert.equal(top('cs', 'svítí PoE zdroj?'), 'poe');
  assert.equal(top('en', 'How do I restart the router and antenna properly?'), 'restart');
  assert.equal(top('en', 'Why is the internet slow?'), 'slow');
  assert.equal(search('cs', 'xyzzy qwerty').length, 0);
});

test('model prompt is grounded in the guide and the check result', () => {
  const p = buildPrompt('cs', 'Co mám dělat?', [KB.cs[0]], 'Výpadek v páteřní síti');
  assert.match(p.system, /POUZE/);
  assert.match(p.user, /PODKLADY:\n# Restart routeru a antény/);
  assert.match(p.user, /VÝSLEDEK KONTROLY:\nVýpadek v páteřní síti/);
  assert.match(buildPrompt('en', 'q', [], null).user, /\(no check yet\)/);
});

test('unrelated questions find nothing (no stopword matches)', () => {
  assert.deepEqual(search('en', 'who won the football match tomorrow'), []);
  assert.equal(search('en', 'can weather affect my antenna?')[0].id, 'signal'); // a real topic still matches
  assert.deepEqual(search('cs', 'kde je moje faktura'), []);
  assert.deepEqual(search('cs', 'jak je to s tím'), []);
});

test('IPv6 addresses parse strictly', () => {
  assert.equal(parseIPv6('2a01:168:331::5'), 0x2a010168033100000000000000000005n);
  assert.equal(parseIPv6('::1'), 1n);
  assert.equal(parseIPv6('::ffff:10.107.77.5'), 0xffff0a6b4d05n);
  for (const bad of ['2a01::168::1', '12345::', '1:2:3:4:5:6:7:8:9', 'g::1', '10.107.77.5', '', null, '::1<script>']) {
    assert.equal(parseIPv6(bad), null, String(bad));
  }
});

test('an IPv6 address is on hkfree.org when an OSPFv3 prefix covers it', () => {
  const t = loadSnapshot({ version: 1, routers: {}, prefixes6: [['2a01:168::/29', '10.107.99.1', 'e'], ['nonsense', '10.107.99.1', 'e'], ['2a01:168:331::/48', 'x', 's']] });
  assert.equal(t.prefixes6.length, 1);
  assert.equal(inNetwork(t, '2a01:168:331::5'), true);
  assert.equal(inNetwork(t, '2001:db8::5'), false);
  assert.equal(inNetwork(t, '10.107.77.5'), false);
});

test('an IPv6 address finds its router via OSPFv3, ignoring the /29 allocation', () => {
  const t = loadSnapshot({
    version: 1,
    routers: {
      '10.107.2.1': { links: [['10.107.99.1', 10, null]] },
      '10.107.99.1': { links: [['10.107.2.1', 10, null]] },
    },
    exits: [{ router: '10.107.99.1', target: '10.107.99.1', e1: false, metric: 1 }],
    prefixes6: [
      ['2a01:168::/29', '10.107.99.1', 'e'],
      ['2a01:168:200:100::/56', '10.107.2.1', 'e'],
      ['2a01:168:a00:1500::/64', '10.107.10.65', 's'],
    ],
  });
  const a = analyze(t, '2a01:168:200:100::5');
  assert.deepEqual(a.hops.map((h) => h.router), ['10.107.2.1', '10.107.99.1']);
  const unknown = analyze(t, '2a01:168:a00:1500::5');
  assert.equal(unknown.pathUnknown, true);
  assert.equal(unknown.hops.length, 0);
  const onlyAllocation = analyze(t, '2a01:168:7::5');
  assert.equal(onlyAllocation.router, null);
  assert.equal(onlyAllocation.pathUnknown, false);
});

test('a hidden part of the network is reached through its border router', () => {
  const t = loadSnapshot({
    version: 1,
    routers: {
      '10.107.10.97': { links: [['10.107.99.1', 10, null]] },
      '10.107.99.1': { links: [['10.107.10.97', 10, null]] },
    },
    exits: [{ router: '10.107.99.1', target: '10.107.99.1', e1: false, metric: 1 }],
    prefixes: [['10.107.10.64/28', '10.107.10.97', 'a'], ['10.107.10.97/32', '10.107.10.97', 's']],
    prefixes6: [['2a01:168:a00:1500::/64', '10.107.10.65', 's'], ['2a01:168:c00::/64', '10.107.200.5', 's']],
  });
  const v4 = analyze(t, '10.107.10.70');
  assert.equal(v4.border, true);
  assert.deepEqual(v4.hops.map((h) => h.router), ['10.107.10.97', '10.107.99.1']);
  const v6 = analyze(t, '2a01:168:a00:1500::5');
  assert.equal(v6.border, true);
  assert.equal(v6.router, '10.107.10.97');
  assert.equal(analyze(t, '10.107.10.97').border, false);
  assert.equal(analyze(t, '2a01:168:c00::5').pathUnknown, true);
});

test('the network is unknown for IPv6 when the map has no IPv6 data', () => {
  const without = loadSnapshot({ version: 1, routers: {}, prefixes: [['10.107.77.0/25', '10.107.77.1', 's']] });
  assert.equal(networkOf(without, '2a01:168:331::5'), 'unknown');
  assert.equal(networkOf(without, '10.107.77.5'), 'hkfree');
  assert.equal(networkOf(without, '192.0.2.7'), 'other');
  const with6 = loadSnapshot({ version: 1, routers: {}, prefixes6: [['2a01:168:331::/48', '10.107.77.1', 's']] });
  assert.equal(networkOf(with6, '2a01:168:331::5'), 'hkfree');
  assert.equal(networkOf(with6, '2001:db8::5'), 'other');
});

test('a border router is found even under a more specific backbone prefix', () => {
  const t = loadSnapshot({
    version: 1,
    routers: { '10.107.10.97': { links: [] }, '10.107.10.1': { links: [] } },
    prefixes: [['10.107.10.64/28', '10.107.10.97', 'a'], ['10.107.10.64/30', '10.107.10.1', 's']],
    prefixes6: [['2a01:168:a00:1500::/64', '10.107.10.65', 's']],
  });
  assert.equal(ownerRouter(t, '2a01:168:a00:1500::5').router, '10.107.10.97');
});
